---筛选类型
--- from: Assets/BundleResources/Prefabs/BattleUI/ScreenPanel.prefab > name: Content
---@class UIScreenType
---@field Env                           	UIScreenType                            
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field Label                         	UnityEngine.RectTransform               	@ 0    
---@field Label2                        	UnityEngine.RectTransform               	@ 1    
---@field Layout                        	UnityEngine.RectTransform               	@ 2    
---@field Layout2                       	UnityEngine.RectTransform               	@ 3    
---@field TextTitle                     	UnityEngine.UI.Text                     	@ 4    
local UIScreenType = Class('UIScreenType')

-------------- import ------------------
local Text = CS.UnityEngine.UI.Text
local GameObject = CS.UnityEngine.GameObject
local KTool = CS.Engine.Lib.KTool
-------------- import ------------------

function UIScreenType:__init()
    ---@type ScreenVo
    self.screenVo = nil
    ---@type integer
    self.type = nil
end

function UIScreenType:__delete()
    self.screenVo = nil
    self.type = nil
    self.controller = nil
end

function UIScreenType:Awake()
    local TextArea = self.controller.transform:Find("TextArea")
    if TextArea then
        KTool.SetActive(TextArea.gameObject, true)
    end
    KTool.SetActive(self.Label.gameObject, false)
    KTool.SetActive(self.Label2.gameObject, false)
end

---FreshNode
---刷新筛选类型
---@param vo ScreenVo 筛选数据
---@param groups table<integer, integer[]> 分组数据
function UIScreenType:FreshNode(vo, groups)
    self.screenVo = vo
    self.type = vo.id
    self.TextTitle.text = vo.type
    self:CreateToggle(groups)
end

---CreateToggle
---生成筛选按钮
---@param groups table<integer, integer[]> 分组数据
function UIScreenType:CreateToggle(groups)
    local parent = self.Layout.gameObject
    local child = self.Label.gameObject
    if self.screenVo.style == Constants.UIScreenStyle.SIX then
        CfUtils.SetActive(self.Layout, true)
        CfUtils.SetActive(self.Layout2, false)
    else
        parent = self.Layout2.gameObject
        child = self.Label2.gameObject
        CfUtils.SetActive(self.Layout, false)
        CfUtils.SetActive(self.Layout2, true)
    end
    --KTool.DestroyGameObjectChildren(parent)
    for i, v in pairs(self.screenVo.condition) do
        xTry(function()
            local go = parent.transform:Find(i)
            if not go then
                go = parent:AddChild(child)
            end
            go.name = i
            KTool.SetActive(go.gameObject, true)
            ---@type ScreenToggle
            local env = CfUtils.GetLuaScr(go, Constants.UILuaTablePath.ScreenToggle)
            if not isNull(env) then
                env:RefreshNode(checkNumber(self.type), self.screenVo.condition[i], self.screenVo.conditionName[i], groups)
            end

        end)
        --KTool.SetActive(go.gameObject, true)
        --KTool.SetParent(go.gameObject, parent, false)
    end
end

function UIScreenType:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIScreenType